type Shipment = {
  id: string;
  serviceTypeId?: string;
  recipientProfileId?: string;
  reference: string;
  recipient: Localized;
  phone: string;
  sender: Localized;
  area: Localized;
  governorate: Localized;
  status: Localized;
  statusPolicyId?: string;
  statusTone: "blue" | "orange" | "green" | "gray" | "red";
  custody: Localized;
  custodyType:
    | "warehouse"
    | "courier"
    | "return_route"
    | "recipient"
    | "sender";
  courier: Localized | null;
  assignedAt?: Localized;
  amount: number;
  deliveryDate: Localized;
  required: Localized;
  requiredType: "none" | "attention" | "incomplete";
  lastEvent: Localized;
  confirmation: Localized;
  confirmationCode?: "confirmed" | "no_answer" | "later" | "not_recorded";
  confirmationHistory?: {
    id: string;
    result: "confirmed" | "no_answer" | "later";
    note: string;
    nextContact: string;
    timestamp: Localized;
  }[];
  statusHistory?: {
    id: string;
    statusPolicyId: string;
    status: Localized;
    color: string;
    recordedBy: Localized;
    collectedAmount: number | null;
    deliveredPieces: number | null;
    returnedPieces: number | null;
    reason: string;
    note: string;
    nextDate: string;
    customValues?: Record<string, string>;
    timestamp: Localized;
    settlementStatus?: "pending" | "settled";
    settlementId?: string;
    settledAt?: Localized;
    senderSettlementStatus?: "eligible" | "reserved" | "settled";
    senderSettlementDraftId?: string;
    senderMoneySettled?: boolean;
    senderReturnSettled?: boolean;
    senderOtherFees?: number;
    senderOtherFeesLabel?: Localized;
    courierCommissionSnapshot?: CourierCommissionSnapshot;
  }[];
  pieces: number;
  /** Company revenue for shipping, resolved from the sender price list. */
  shippingFee: number;
  /** Shipping amount shown to and collected from the recipient. */
  recipientShippingCharge?: number;
  /** Pricing source saved with the shipment so later policy edits do not rewrite history. */
  recipientShippingSource?: "company" | "custom";
  recipientShippingAreaId?: string;
  sourceTrustId?: string;
  /** Collection instruction saved by the registration employee. */
  shippingPayer: "recipient" | "sender";
  /** Final accounting classification confirmed during courier settlement. */
  finalShippingPayer?: "recipient" | "sender";
  finalShippingPayerSource?: "registered" | "accountant_correction";
  finalShippingPayerReason?: string;
  finalShippingPayerBy?: Localized;
  finalShippingPayerAt?: Localized;
  customValues?: Record<string, string>;
  customFinancialSnapshot?: {
    recipientAdditions: number;
    senderDeductions: number;
    companyCosts: number;
  };
  warehouseLocation?: string;
  warehouseHistory?: WarehouseMovement[];
  replacementHistory?: ShipmentReplacementEvent[];
  address: Localized;
};

type ShipmentReplacementEvent = {
  id: string;
  kind: "courier" | "sender";
  from: Localized;
  to: Localized;
  performedBy: Localized;
  timestamp: Localized;
  note: string;
};

type ShipmentReplacementRecord = ShipmentReplacementEvent & {
  shipmentIds: string[];
  warnings: string[];
};

function shipmentCompanyShippingFee(shipment: Shipment) {
  return shipment.shippingFee;
}

function shipmentRecipientShippingRate(shipment: Shipment) {
  return (
    shipment.recipientShippingCharge ??
    shipment.shippingFee
  );
}

function shipmentRecipientShippingCharge(shipment: Shipment) {
  return shipment.shippingPayer === "recipient"
    ? shipmentRecipientShippingRate(shipment)
    : 0;
}

function shipmentFinalShippingPayer(shipment: Shipment) {
  return shipment.finalShippingPayer ?? shipment.shippingPayer;
}

function shipmentAccountingRecipientShippingCharge(shipment: Shipment) {
  return shipmentFinalShippingPayer(shipment) === "recipient"
    ? shipmentRecipientShippingRate(shipment)
    : 0;
}

function shipmentTotalToCollect(shipment: Shipment) {
  return (
    shipment.amount +
    shipmentRecipientShippingCharge(shipment) +
    (shipment.customFinancialSnapshot?.recipientAdditions ?? 0)
  );
}

function shipmentSenderBaseDue(shipment: Shipment) {
  return (
    shipment.amount +
    shipmentAccountingRecipientShippingCharge(shipment) -
    shipmentCompanyShippingFee(shipment) -
    (shipment.customFinancialSnapshot?.senderDeductions ?? 0)
  );
}

