function normalizePhone(value: string) {
  return value.replace(/\D/g, "");
}

function recipientAddress(
  id: string,
  ar: string,
  en: string,
  governorateId: string,
  areaId: string,
  primary = true,
): RecipientAddress {
  return {
    id,
    label: {
      ar: primary ? "العنوان الأساسي" : "عنوان إضافي",
      en: primary ? "Primary address" : "Additional address",
    },
    address: { ar, en },
    governorateId,
    areaId,
    primary,
    createdAt: { ar: "سجل محفوظ", en: "Saved record" },
  };
}

function archivedRecipientExperience(
  id: string,
  shipmentId: string,
  reference: string,
  sender: Localized,
  result: RecipientExperience["result"],
  confirmation: RecipientExperience["confirmation"],
  timestamp: Localized,
  addressId: string,
): RecipientExperience {
  return {
    id,
    shipmentId,
    reference,
    sender,
    result,
    confirmation,
    timestamp,
    addressId,
    archived: true,
  };
}

