type AreaRecord = {
  id: string;
  name: Localized;
  code: string;
  state: "active" | "paused";
  order: number;
  aliases: string[];
  pricedLists: number;
  shipments: number;
  assignmentAllowed: boolean;
};

type GovernorateRecord = {
  id: string;
  name: Localized;
  code: string;
  state: "active" | "paused";
  order: number;
  areas: AreaRecord[];
};

type GeoEditorState = {
  kind: "governorate" | "area";
  isNew: boolean;
  governorateId: string;
  draft: {
    id: string;
    name: Localized;
    code: string;
    state: "active" | "paused";
    order: number;
    aliases: string[];
    assignmentAllowed: boolean;
  };
};

