function normalizeCourierRatePlan(plan: CourierRatePlan): CourierRatePlan {
  const isLegacyMixedPlan =
    plan.compensationType === "mixed" || plan.code === "COURIER-MIXED";
  const compensationType = isLegacyMixedPlan ? "salary" : plan.compensationType;
  const settlementCycle =
    isLegacyMixedPlan
      ? "weekly"
      : compensationType === "salary"
      ? plan.settlementCycle === "weekly"
        ? "weekly"
        : "monthly"
      : plan.settlementCycle === "daily"
        ? "instant"
        : plan.settlementCycle;
  return {
    ...plan,
    name: isLegacyMixedPlan
      ? { ar: "مرتب أسبوعي ثابت", en: "Fixed weekly salary" }
      : plan.name,
    code: isLegacyMixedPlan ? "COURIER-WEEKLY-SALARY" : plan.code,
    state: isLegacyMixedPlan ? "active" : plan.state,
    compensationType,
    settlementCycle,
    fixedSalary:
      compensationType === "commission"
        ? null
        : Math.max(0, isLegacyMixedPlan ? 1800 : (plan.fixedSalary ?? 0)),
    effectiveFrom: plan.effectiveFrom ?? "2026-08-01",
  };
}

function cloneCourierRateMatrix(rates: PriceMatrix): PriceMatrix {
  return Object.fromEntries(
    Object.entries(rates).map(([areaId, areaRates]) => [
      areaId,
      { ...areaRates },
    ]),
  );
}

function normalizeCourierPlans(
  plans: CourierRatePlan[],
  couriers: CourierRecord[],
): CourierRatePlan[] {
  const normalizedPlans = (plans.length ? plans : courierRatePlansData).map(
    normalizeCourierRatePlan,
  );
  const activeCouriers = couriers.filter((courier) => courier.state === "active");

  return activeCouriers.map((courier, index) => {
    const individualAgreement = normalizedPlans.find(
      (plan) =>
        plan.couriers.length === 1 &&
        (plan.couriers[0]?.en === courier.name.en ||
          plan.couriers[0]?.ar === courier.name.ar),
    );
    const inheritedAgreement = normalizedPlans.find((plan) =>
      plan.couriers.some(
        (assignedCourier) =>
          assignedCourier.en === courier.name.en ||
          assignedCourier.ar === courier.name.ar,
      ),
    );
    const source =
      individualAgreement ??
      inheritedAgreement ??
      normalizedPlans.find((plan) => plan.isDefault) ??
      normalizedPlans[index % Math.max(normalizedPlans.length, 1)] ??
      courierRatePlansData[0];

    return normalizeCourierRatePlan({
      ...source,
      id: `courier-agreement-${courier.id}`,
      name: {
        ar: `اتفاق أجر ${courier.name.ar}`,
        en: `${courier.name.en} pay agreement`,
      },
      code: `PAY-${courier.code}`,
      isDefault: false,
      couriers: [courier.name],
      coveredAreaIds: source.coveredAreaIds
        ? [...source.coveredAreaIds]
        : undefined,
      rates: cloneCourierRateMatrix(source.rates),
    });
  });
}

function resolveCourierPayPlan(
  courier: Localized,
  plans: CourierRatePlan[],
) {
  return (
    plans.find(
      (plan) =>
        plan.state === "active" &&
        plan.couriers.some(
          (assignedCourier) =>
            assignedCourier.en === courier.en ||
            assignedCourier.ar === courier.ar,
        ),
    ) ??
    plans.find((plan) => plan.state === "active" && plan.isDefault) ??
    null
  );
}

function captureCourierCommissionSnapshot({
  courier,
  shipment,
  statusPolicyId,
  plans,
  governorates,
  capturedAt,
}: {
  courier: Localized;
  shipment: Shipment;
  statusPolicyId: string;
  plans: CourierRatePlan[];
  governorates: GovernorateRecord[];
  capturedAt: Localized;
}): CourierCommissionSnapshot {
  const plan = resolveCourierPayPlan(courier, plans);
  if (!plan) {
    return {
      planId: null,
      planName: null,
      planCode: null,
      planVersion: null,
      compensationType: null,
      settlementCycle: null,
      areaId: null,
      statusPolicyId,
      amount: null,
      resolution: "missing_plan",
      capturedAt,
    };
  }

  const base = {
    planId: plan.id,
    planName: plan.name,
    planCode: plan.code,
    planVersion: plan.version,
    compensationType: plan.compensationType,
    settlementCycle: plan.settlementCycle,
    statusPolicyId,
    capturedAt,
  };

  if (plan.compensationType === "salary") {
    return {
      ...base,
      areaId: null,
      amount: 0,
      resolution: "salary",
    };
  }

  const area = governorates
    .flatMap((governorate) => governorate.areas)
    .find(
      (candidate) =>
        candidate.name.en === shipment.area.en ||
        candidate.name.ar === shipment.area.ar,
    );
  if (!area) {
    return {
      ...base,
      areaId: null,
      amount: null,
      resolution: "missing_area",
    };
  }

  const amount = plan.rates[area.id]?.[statusPolicyId] ?? null;
  return {
    ...base,
    areaId: area.id,
    amount,
    resolution: amount == null ? "missing_rate" : "priced",
  };
}

function courierCommissionDueAt(
  cycle: CourierSettlementCycle | null,
  from: Date,
) {
  const due = new Date(from);
  if (cycle === "weekly") {
    const daysUntilSaturday = (6 - due.getDay() + 7) % 7;
    due.setDate(due.getDate() + daysUntilSaturday);
    due.setHours(23, 59, 59, 999);
  } else if (cycle === "monthly") {
    due.setMonth(due.getMonth() + 1, 0);
    due.setHours(23, 59, 59, 999);
  }
  return due.toISOString();
}

