type ShipmentFieldMode =
  | "required_on_create"
  | "optional"
  | "required_before_assignment"
  | "hidden";

type ShipmentFieldGroup =
  | "recipient"
  | "address"
  | "shipment"
  | "financial"
  | "sender";

type ShipmentFieldDataType =
  | "short_text"
  | "long_text"
  | "number"
  | "money"
  | "phone"
  | "date"
  | "single_choice"
  | "multi_choice"
  | "boolean";

type ShipmentFieldPlacement =
  | "entry"
  | "details"
  | "courier"
  | "sender"
  | "waybill"
  | "reports";

type ShipmentFieldRole = "information" | "operational" | "financial";

type ShipmentFieldFinancialEffect =
  | "none"
  | "add_recipient"
  | "deduct_sender"
  | "company_cost";

type ShipmentFieldPolicy = {
  id: string;
  name: Localized;
  code: string;
  group: ShipmentFieldGroup;
  description: Localized;
  mode: ShipmentFieldMode;
  custom: boolean;
  inExcel: boolean;
  order: number;
  dataType?: ShipmentFieldDataType;
  placements?: ShipmentFieldPlacement[];
  searchable?: boolean;
  role?: ShipmentFieldRole;
  financialEffect?: ShipmentFieldFinancialEffect;
};

type ShippingChargeMode =
  | "company_price"
  | "company_plus"
  | "fixed"
  | "manual";

type RecipientAreaRate = {
  source: "company" | "custom";
  amount: number;
};

type ShipmentDataSettings = {
  confirmationMode: "off" | "optional" | "required_before_assignment";
  confirmationAttempts: number;
  allowAssignmentWithoutConfirmation: boolean;
  incompleteRoute: "warehouse_and_queue" | "complete_before_warehouse";
  trustsEnabled: boolean;
  shippingPayerOverride: boolean;
  phoneLookupEnabled: boolean;
  defaultShippingPayer: "recipient" | "sender";
  shippingChargeMode: ShippingChargeMode;
  shippingChargeValue: number;
  recipientPriceDisplay: "total_only" | "separate_shipping";
  manualEntryEnabled: boolean;
  batchEntryEnabled: boolean;
  excelImportEnabled: boolean;
  duplicateCheckMode: "block" | "warn" | "off";
  senderReferenceMode: "required_unique" | "optional_unique" | "optional";
  packageInspection: "not_allowed" | "allowed" | "sender_approval";
  partialDeliveryEnabled: boolean;
  deliveryProof: "recipient_name" | "signature" | "photo" | "otp";
  labelDetailMode: "full" | "masked" | "minimal";
  collectionWarningLimit: number;
};

type SenderShipmentPolicy = {
  sender: Localized;
  fields: ShipmentFieldPolicy[];
  settings: ShipmentDataSettings;
  recipientAreaRates?: Record<string, RecipientAreaRate>;
  state?: "draft" | "published";
  version?: number;
  updatedAt?: Localized;
  updatedBy?: Localized;
  history?: SenderPolicyHistoryEntry[];
  overrideKeys?: (keyof ShipmentDataSettings)[];
  fieldOverrideCodes?: string[];
};

type SenderPolicyHistoryEntry = {
  version: number;
  state: "draft" | "published";
  updatedAt: Localized;
  updatedBy: Localized;
  fields: ShipmentFieldPolicy[];
  settings: ShipmentDataSettings;
  recipientAreaRates?: Record<string, RecipientAreaRate>;
  overrideKeys?: (keyof ShipmentDataSettings)[];
  fieldOverrideCodes?: string[];
};

function normalizeShipmentField(field: ShipmentFieldPolicy): ShipmentFieldPolicy {
  return {
    ...field,
    dataType:
      field.dataType ??
      (field.code.includes("PHONE")
        ? "phone"
        : field.code === "DELIVERY_DATE"
          ? "date"
          : field.group === "financial" || field.code === "PIECE_COUNT"
            ? "number"
            : field.code === "NOTES" || field.code === "DELIVERY_ADDRESS"
              ? "long_text"
              : "short_text"),
    placements: field.placements ?? [
      "entry",
      "details",
      ...(field.group === "financial" ? (["sender"] as ShipmentFieldPlacement[]) : []),
    ],
    searchable:
      field.searchable ??
      ["RECIPIENT_PHONE", "RECIPIENT_NAME", "SENDER_REFERENCE"].includes(
        field.code,
      ),
    role:
      field.role ??
      (field.group === "financial"
        ? "financial"
        : field.group === "shipment"
          ? "operational"
          : "information"),
    financialEffect: field.financialEffect ?? "none",
  };
}

