function normalizeShipmentDataSettings(
  settings?: Partial<ShipmentDataSettings>,
): ShipmentDataSettings {
  return {
    ...shipmentDataSettingsDefault,
    ...settings,
  };
}

function findSenderShipmentPolicy(
  sender: Localized,
  senderPolicies: SenderShipmentPolicy[],
) {
  return senderPolicies.find(
    (policy) =>
      policy.sender.en === sender.en || policy.sender.ar === sender.ar,
  );
}

function findEffectiveSenderShipmentPolicy(
  sender: Localized,
  senderPolicies: SenderShipmentPolicy[],
) {
  const policy = findSenderShipmentPolicy(sender, senderPolicies);
  return policy && (policy.state ?? "published") === "published"
    ? policy
    : undefined;
}

function resolveSenderPolicySettings(
  sender: Localized,
  companySettings: ShipmentDataSettings,
  senderPolicies: SenderShipmentPolicy[],
) {
  const base = normalizeShipmentDataSettings(companySettings);
  const policy = findEffectiveSenderShipmentPolicy(sender, senderPolicies);
  if (!policy) return base;
  const policySettings = normalizeShipmentDataSettings(policy.settings);
  if (!policy.overrideKeys) return policySettings;
  const resolved = { ...base };
  policy.overrideKeys.forEach((key) => {
    if (key === "trustsEnabled") return;
    (resolved[key] as ShipmentDataSettings[typeof key]) =
      policySettings[key];
  });
  return resolved;
}

function resolveSenderPolicyFields(
  sender: Localized,
  companyFields: ShipmentFieldPolicy[],
  senderPolicies: SenderShipmentPolicy[],
) {
  const base = companyFields.map(normalizeShipmentField);
  const policy = findEffectiveSenderShipmentPolicy(sender, senderPolicies);
  if (!policy) return base;
  const policyFields = policy.fields.map(normalizeShipmentField);
  if (!policy.fieldOverrideCodes) return policyFields;
  const policyByCode = new Map(
    policyFields.map((field) => [field.code, field]),
  );
  const merged = base.map((field) =>
    policy.fieldOverrideCodes?.includes(field.code)
      ? policyByCode.get(field.code) ?? field
      : field,
  );
  policyFields
    .filter(
      (field) =>
        field.custom &&
        !merged.some((mergedField) => mergedField.code === field.code),
    )
    .forEach((field) => merged.push(field));
  return merged;
}

function resolveShipmentDataSettings(
  shipment: Shipment,
  companySettings: ShipmentDataSettings,
  senderPolicies: SenderShipmentPolicy[],
) {
  return resolveSenderPolicySettings(
    shipment.sender,
    companySettings,
    senderPolicies,
  );
}

function calculateRecipientShippingCharge(
  companyFee: number,
  payer: "recipient" | "sender",
  settings: ShipmentDataSettings,
  manualValue: string,
) {
  if (payer === "sender") return 0;
  if (settings.shippingChargeMode === "company_plus") {
    return Math.max(0, companyFee + settings.shippingChargeValue);
  }
  if (settings.shippingChargeMode === "fixed") {
    return Math.max(0, settings.shippingChargeValue);
  }
  if (settings.shippingChargeMode === "manual") {
    return Math.max(0, Number(manualValue) || 0);
  }
  return Math.max(0, companyFee);
}

function companyDeliveryPriceForArea(
  priceList: PriceListRecord | null,
  statuses: StatusPolicy[],
  areaId: string,
) {
  const deliveredStatus =
    statuses.find(
      (status) =>
        status.state === "published" &&
        status.appearsInPricing &&
        status.code.toUpperCase() === "DELIVERED",
    ) ??
    statuses.find(
      (status) => status.state === "published" && status.appearsInPricing,
    );
  if (!priceList || !deliveredStatus) return null;
  const price = priceList.prices[areaId]?.[deliveredStatus.id];
  return typeof price === "number" ? price : null;
}

function recipientAreaShippingCharge(
  companyFee: number,
  payer: "recipient" | "sender",
  sender: Localized,
  areaId: string,
  senderPolicies: SenderShipmentPolicy[],
) {
  if (payer === "sender") return 0;
  const policy = findEffectiveSenderShipmentPolicy(sender, senderPolicies);
  const rate = policy?.recipientAreaRates?.[areaId];
  return Math.max(
    0,
    rate?.source === "custom" ? rate.amount : companyFee,
  );
}

