  function saveShipmentRecords(records: Shipment[]) {
    const preparedRecords = records.map((record) => {
      if (record.recipientProfileId) return record;
      const newRecipientId = `recipient-${record.id.toLowerCase()}`;
      const governorate = sharedGovernorates.find(
        (candidate) =>
          candidate.name.en === record.governorate.en ||
          candidate.name.ar === record.governorate.ar,
      );
      const area = governorate?.areas.find(
        (candidate) =>
          candidate.name.en === record.area.en ||
          candidate.name.ar === record.area.ar,
      );
      const timestamp: Localized = {
        ar: new Date().toLocaleString("ar-EG", {
          dateStyle: "medium",
          timeStyle: "short",
        }),
        en: new Date().toLocaleString("en-EG", {
          dateStyle: "medium",
          timeStyle: "short",
        }),
      };
      setSharedRecipients((current) => [
        {
          id: newRecipientId,
          name: record.recipient,
          phones: [record.phone],
          addresses: [
            {
              id: `recipient-address-${record.id.toLowerCase()}`,
              label: { ar: "العنوان الأساسي", en: "Primary address" },
              address: record.address,
              governorateId: governorate?.id ?? "",
              areaId: area?.id ?? "",
              primary: true,
              createdAt: timestamp,
            },
          ],
          archivedExperiences: [],
          senderViews: [],
          notes: [],
          createdAt: timestamp,
          updatedAt: timestamp,
        },
        ...current,
      ]);
      return { ...record, recipientProfileId: newRecipientId };
    });
    setSharedShipments((current) => [...preparedRecords, ...current]);
    if (!trustConversionTarget || records.length !== 1) return;
    const shipment = preparedRecords[0];
    const now = new Date();
    const timestamp: Localized = {
      ar: now.toLocaleString("ar-EG", {
        dateStyle: "medium",
        timeStyle: "short",
      }),
      en: now.toLocaleString("en-EG", {
        dateStyle: "medium",
        timeStyle: "short",
      }),
    };
    setSharedTrusts((current) =>
      current.map((record) =>
        record.id === trustConversionTarget.id
          ? {
              ...record,
              state: "resolved" as const,
              resolution: "converted" as const,
              linkedShipmentId: shipment.id,
              resolvedAt: timestamp,
              history: [
                {
                  id: `trust-event-converted-${Date.now()}`,
                  type: "converted" as const,
                  title: {
                    ar: "تحولت إلى شحنة جديدة",
                    en: "Converted to new shipment",
                  },
                  details: {
                    ar: `نجح إنشاء الشحنة ${shipment.id} وتوقّف باركود الأمانة عن الاستخدام التشغيلي.`,
                    en: `Shipment ${shipment.id} was created and the trust barcode stopped operational use.`,
                  },
                  performedBy: { ar: "أحمد حسن", en: "Ahmed Hassan" },
                  timestamp,
                },
                ...record.history,
              ],
            }
          : record,
      ),
    );
    setTrustConversionTarget(null);
    setScreen("trusts");
  }

